import{z as o,x as A,o as t,c as d,q as B,j as i,D as l,d as E,s,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const q=JSON.parse('{"title":"离散股息对美式期权","description":"","frontmatter":{"title":"离散股息对美式期权","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/discrete-dividend-am.md","filePath":"quant/discrete-dividend-am.md","lastUpdated":1791063341000}'),p={name:"quant/discrete-dividend-am.md"};function D(m,a,h,u,C,S){const r=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=B('<h1 id="离散股息对美式期权" tabindex="-1">离散股息对美式期权 <a class="header-anchor" href="#离散股息对美式期权" aria-label="Permalink to &quot;离散股息对美式期权&quot;">​</a></h1><div class="epigraph"><p>单笔已知现金股息下，美式看涨的提前行权几乎只会发生在除权前夕：持有人比较的是「锁定股息」与「丢掉剩余保险」这两件事，而不是把连续红利率再积分一遍。</p><footer>—— 据 Merton 对股利与提前行权的论述，以及 Roll–Geske–Whaley 对单笔离散股息美式看涨的处理整理</footer></div><p><a href="/quant/higher-greeks">上一课</a>把 Charm 写成 Delta 的时间导数、Color 写成 Gamma 的时间导数；现货静止时它们仍推动隔夜头寸。高阶希腊假定红利率连续或没有现金除权。连续 \\(q\\) 适合指数；个股的现金股息是日历上的跳跃。缺口是美式决策钉在除权前的那一个时点上——无股利美式看涨不应执行，有离散股息时这个结论不再自动成立。把 \\(q\\) 当成「平均股息率」塞进 Black-Scholes，对美式个股会系统性错价。本课写现金股息如何改写自由边界；网格倒推见 <a href="/quant/binomial-tree">二叉树</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>持有美式看涨、标的即将派发现金股息时，续持意味着除权后股价下跳、内在价值可能立刻变差；立即执行则拿到股票并收到股息，但永远失去把执行价再推迟支付的利息，以及股价继续上涨的凸性。问题是：这个权衡是否只在除权瞬间有意义，还是在两个除权日之间的整个区间里都可能执行。对于现金股息（金额已知、除权日已知），答案几乎总是：看涨的执行区域贴在除权前夕，其余时间更接近欧式。看跌则相反，利息动机在整个生命期内都可能触发执行，股息只是修正边界位置。</p><p><span class="marginnote">数字实例：股价 50 元、现金股息 2 元的股票，除权瞬间现货直接下跳 4%。若一张实值看涨此刻的剩余时间价值只有 1 元，执行换 2 元股息净赚 1 元；若剩余时间价值有 3 元，退保就亏。判断依据只有「\\(D\\) 对剩余时间价值」这一个比较。</span></p><p>把离散股息误写成常数 \\(q\\)，会把「除权前一次集中的执行动机」抹成「每天漏一点」。对欧式，这种平均有时还能当工程近似；对美式，自由边界的形状被改写，提前行权溢价的期限结构会错。工程问题因此是：状态变量在除权日如何跳跃、续持价值在跳跃两侧如何匹配、以及多笔股息时组合爆炸还能否闭式处理。</p><p><span class="marginnote">常见误区：初学者容易以为「年化 4% 的股息率」与「一年一次跳 4%」只是写法不同。对欧式远期二者等价，都能对上；但「什么时候允许执行」这个美式问题对时间表极其敏感——脉冲式的单次下跳和每天渗漏给出的自由边界完全不是一回事。</span></p><h3 id="除权跳跃与托管模型" tabindex="-1">除权跳跃与托管模型 <a class="header-anchor" href="#除权跳跃与托管模型" aria-label="Permalink to &quot;除权跳跃与托管模型&quot;">​</a></h3><p>记除权日 \\(t_d\\)，现金股息 \\(D\\)（已宣告，视为无风险）。除权瞬间现货满足 \\(S_{t_d+}=S_{t_d-}-D\\)（忽略税收与借券调整）。风险中性下，除权日之间 \\(S\\) 仍是几何布朗；到了 \\(t_d\\) 发生一次确定的下跳。托管（escrowed）模型把股息现值从现价里抠掉，令 \\(S^\\ast=S-\\mathrm{PV}(D)\\)，再对 \\(S^\\ast\\) 跑无股利公式。欧式看涨可以这样把终端支付写成只依赖除权后过程；美式不行：执行发生在除权前，持有人拿到的是含息现货 \\(S\\)，不是 \\(S^\\ast\\)，托管把执行决策的标的改错了。</p><p><span class="marginnote">托管模型不是「把股息忘了」，而是把股息当成独立的现金券从股价里剥离。欧式终端只看见除权后的 \\(S^\\ast\\) 路径，剥离合法；美式在除权前比较 \\(S-K\\) 与续持，剥离会系统性压低提前行权溢价。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>单笔股息的美式看涨，经典闭式路线是 Roll（1977）、Geske（1979）、Whaley（1981）：除权前是否执行，等价于把「除权后的欧式看涨」当成标的的复合期权，临界现货 \\(S^\\ast\\) 由价值匹配给出。临界条件的直觉是：\\(D\\) 必须大到超过剩余时间价值，否则即使除权也不执行。多笔股息时复合期权的层数随除权次数增加，Haug、Haug 与 Lewis（2003）给出可计算的近似与数值方案，工程上更常直接上树或 PDE。</p><p>数值上，<a href="/quant/binomial-tree">二叉树</a> 或三叉必须把除权日对齐到时间层：该层每个节点先比较执行，再减去 \\(D\\)，再向后继贴现。不对齐就会把一次跳跃摊到两步里，执行区域被稀释。有限差分同样要把网格点钉在 \\(t_d\\)，跳跃用插值接到 \\(S-D\\) 处的续持价值。LSMC 把除权后的价格写进路径，回归的状态在除权前应包含「距下一次除权的时间」以及预期 \\(D\\)，否则基函数看不见集中在 \\(t_d\\) 的执行动机。</p><h3 id="roll–geske–whaley-与多笔股息" tabindex="-1">Roll–Geske–Whaley 与多笔股息 <a class="header-anchor" href="#roll–geske–whaley-与多笔股息" aria-label="Permalink to &quot;Roll–Geske–Whaley 与多笔股息&quot;">​</a></h3><p>单笔已知 \\(D\\) 时，除权后的合约是无股利美式看涨，因而等于欧式，Black-Scholes 可用。除权前的问题是：若执行，得 \\(S-K\\)；若不执行，得一张以除权后现货为标的的欧式看涨。使二者相等的 \\(S\\) 就是临时自由边界。\\(D/S\\) 很小或剩余期限很长时，这个根可能不存在，即除权前也不执行。多笔股息把「除权后的欧式」变成「仍可能在后续除权前执行的美式」，闭式链条断开。实践中两到三笔已宣告股息用树最干净；更多笔或不确定股息政策，应把 \\(D\\) 当成带公告风险的状态，而不是常数。</p><p>不确定股息（政策未宣告、或与盈利挂钩）会重新引入连续 \\(q\\) 的影子：市场用隐含的预期漏出给远期定价。此时美式个股期权的执行动机不再钉死在已知的 \\(t_d\\)，自由边界又散回整个区间。方法上应先声明股息是已宣告现金还是隐含红利率，再选公式。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>经济机制是保险对股息。看涨的时间价值来自凸性与延迟支付 \\(K\\) 的利息；现金股息是把一部分价值确定地从股价里搬走，持有期权的人拿不到这笔现金（除非合约有特殊分红保护）。当 \\(D\\) 大于剩余时间价值，提前执行等于用保险去换股息。除权日之间没有新的现金漏出，Merton 的无股利论证恢复，看涨不应执行。这就是「几乎只在除权前夕」这句话的来源：不是数值巧合，而是现金流日历。</p><p>看跌的机制不对称。执行看跌立刻拿到 \\(K\\) 去吃利息，股息会压低现货、增加看跌的续持价值，因此离散股息通常推迟看跌的执行、压低提前行权溢价。把看涨与看跌的美式溢价用同一套 \\(q\\) 去调，会把两个相反的日历效应拧成一个参数。</p><p><span class="marginnote">直觉类比：时间价值像保险费，提前执行等于退保换现金。没有股息的美式看涨没有「触发退保的事件」，所以理论上永不提前执行；现金股息就是那个事件，而且日期写在日历上。</span></p><p>对冲层面，除权附近 \\(\\Delta\\) 与 \\(\\Gamma\\) 剧烈：自由边界若被碰到，持有人成批执行，做市商从期权空头变成现货多头，还要处理借券与股息税收。离散对冲误差在这一天会远大于普通交易日，不能用平均 \\(\\Gamma\\) 去估。</p><h3 id="连续红利率不是离散股息的极限捷径" tabindex="-1">连续红利率不是离散股息的极限捷径 <a class="header-anchor" href="#连续红利率不是离散股息的极限捷径" aria-label="Permalink to &quot;连续红利率不是离散股息的极限捷径&quot;">​</a></h3><p>形式上，把一年内的现金股息摊成 \\(q\\approx D/S\\) 再送进 Merton 的连续股利公式，只能匹配远期，不能匹配美式自由边界。极限成立的条件是股息连续漏出；一年一次的现金 \\(D\\) 无论多小，执行动机仍是脉冲，不是密度。短期限、深实值、高股息率的个股看涨，这种摊销会低估除权前执行概率、高估除权后仍应付的时间价值。指数期权用 \\(q\\) 是因为成分股除权被平滑；个股美式用 \\(q\\) 是图省事。</p><p><span class="marginnote">分红保护条款（执行价下调、或现金补偿）会取消「用执行去抢股息」的动机，美式看涨重新接近欧式。读合约比选模型更先：同一标的、不同交易所的条款不必相同。</span></p><p>同一笔股息推到看涨与看跌身上，作用方向相反，这正是「一个 \\(q\\) 调不了两个方向」的结构性原因：</p>',26)),(t(),i(n,null,{default:l(()=>[s(r,{id:"mermaid-76",class:"mermaid",graph:"flowchart%20LR%0A%20%20Div%5B%22%E9%99%A4%E6%9D%83%3A%20%E7%8E%B0%E9%87%91%20D%20%E4%BD%BF%20S%20%E4%B8%8B%E8%B7%B3%22%5D%20--%3E%20Call%5B%22%E7%9C%8B%E6%B6%A8%3A%20%E6%8B%BF%E4%B8%8D%E5%88%B0%E8%82%A1%E6%81%AF%2C%20%E6%97%B6%E9%97%B4%E4%BB%B7%E5%80%BC%E8%A2%AB%E6%90%AC%E8%B5%B0%22%5D%0A%20%20Div%20--%3E%20Put%5B%22%E7%9C%8B%E8%B7%8C%3A%20%E5%86%85%E5%9C%A8%E4%BB%B7%E5%80%BC%E6%8A%AC%E5%8D%87%2C%20%E7%BB%AD%E6%8C%81%E6%9B%B4%E5%80%BC%E9%92%B1%22%5D%0A%20%20Call%20--%3E%20CallM%5B%22%E6%89%A7%E8%A1%8C%E5%8A%A8%E6%9C%BA%E9%9B%86%E4%B8%AD%E5%9C%A8%E9%99%A4%E6%9D%83%E5%89%8D%2C%20%E6%9D%A1%E4%BB%B6%E6%98%AF%20D%20%E8%B6%85%E8%BF%87%E5%89%A9%E4%BD%99%E6%97%B6%E9%97%B4%E4%BB%B7%E5%80%BC%22%5D%0A%20%20Put%20--%3E%20PutM%5B%22%E5%88%A9%E6%81%AF%E5%8A%A8%E6%9C%BA%E8%B4%AF%E7%A9%BF%E5%85%A8%E7%A8%8B%2C%20%E8%82%A1%E6%81%AF%E6%8E%A8%E8%BF%9F%E6%89%A7%E8%A1%8C%22%5D%0A%20%20CallM%20--%3E%20Asym%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%20q%20%E6%97%A0%E6%B3%95%E5%90%8C%E6%97%B6%E6%8B%9F%E5%90%88%E4%B8%A4%E4%B8%AA%E6%96%B9%E5%90%91%E7%9A%84%E7%BE%8E%E5%BC%8F%E6%BA%A2%E4%BB%B7%22%5D%0A%20%20PutM%20--%3E%20Asym%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"边界",tabindex:"-1"},[E("边界 "),e("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[4]||(a[4]=e("p",null,"已宣告、确定金额、确定除权日、无税收摩擦，是闭式与标准树的舒适区。特殊股息、股票股息、可选现金/股票、以及除权日与期权到期日过近（来不及再对冲），都会破坏 \\(S\\to S-D\\) 的简单跳跃。美式期货期权的「股息」是持有成本，不是现金 \\(D\\)，不要把个股公式搬过去。",-1)),a[5]||(a[5]=e("p",null,"数值边界：股息大于节点上的 \\(S\\) 时要截断，否则出现负现货；深度实值看涨在除权前几乎必然执行，树的早期层应检查 \\(S-K\\) 是否已压过续持，避免舍入把执行点推后一步。LSMC 在除权日附近样本路径的执行标签对基函数极度敏感，一维香草没有理由不用对齐除权日的树。",-1)),a[6]||(a[6]=e("p",null,[E("不要用本篇去替代 "),e("a",{href:"/quant/american-exercise"},"提前行权"),E(" 里的停时理论：那里处理的是一般美式；这里只把离散现金股息这一条制度写清楚。也不要把托管 \\(S^\\ast\\) 的隐含波动率与含息现货的隐含波动率当成同一曲面。")],-1)),a[7]||(a[7]=e("p",null,[e("span",{class:"marginnote"},"A 股现金分红、送转与除权除息在价格与持仓上同时调整，期权合约的调整规则以交易所通知为准。把美股 \\(S-D\\) 直接套到沪深 300 个股期权，先读调整公告，再谈自由边界。")],-1)),(t(),i(n,null,{default:l(()=>[s(r,{id:"mermaid-92",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%90%AB%E6%81%AF%E7%8E%B0%E8%B4%A7%20S%22%5D%20--%3E%20Dec%5B%22%E9%99%A4%E6%9D%83%E5%89%8D%3A%20%E6%AF%94%E8%BE%83%20S-K%20%E4%B8%8E%E7%BB%AD%E6%8C%81%22%5D%0A%20%20Dec%20--%3E%7C%22S-K%20%E6%9B%B4%E5%A4%A7%22%7C%20Ex%5B%22%E6%89%A7%E8%A1%8C%2C%20%E6%94%B6%E5%8F%96%E8%82%A1%E6%81%AF%22%5D%0A%20%20Dec%20--%3E%7C%22%E7%BB%AD%E6%8C%81%E6%9B%B4%E5%A4%A7%22%7C%20Hold%5B%22%E8%B6%8A%E8%BF%87%E9%99%A4%E6%9D%83%22%5D%0A%20%20Hold%20--%3E%20Jump%5B%22S%20%E2%86%90%20S-D%22%5D%0A%20%20Jump%20--%3E%20Euro%5B%22%E6%AD%A4%E5%90%8E%E8%8B%A5%E6%97%A0%E6%9B%B4%E5%A4%9A%E8%82%A1%E6%81%AF%3A%20%E7%9C%8B%E6%B6%A8%E6%8C%89%E6%AC%A7%E5%BC%8F%22%5D%0A%20%20Ex%20--%3E%20Cash%5B%22%E8%82%A1%E7%A5%A8%20%2B%20%E7%8E%B0%E9%87%91%20D%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=B('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>个股现金股息是除权日的确定下跳，不是连续红利率 \\(q\\)；美式看涨的执行动机集中在除权前夕。</li><li>托管模型对欧式合法，对美式会改错执行标的，系统性压低提前行权溢价。</li><li>单笔已知股息的美式看涨可用 Roll–Geske–Whaley 型复合期权；多笔股息优先对齐除权日的树或 PDE。</li><li>看跌的利息动机贯穿存续期，股息通常推迟而非触发执行，不能与看涨共用一个 \\(q\\) 故事。</li><li>分红保护、特殊股息与合约调整规则会取消或改写这一机制。</li><li>一维香草应对齐除权日做倒推；LSMC 的状态必须看见下一次除权。</li><li>出处：Merton, <em>Bell Journal</em>, 1973；Roll, <em>Journal of Financial Economics</em>, 1977；Geske, 1979；Whaley, 1981；多笔股息的计算见 Haug, Haug and Lewis, 2003。</li></ul>',2))])}const f=o(p,[["render",D]]);export{q as __pageData,f as default};
